export const useEditorStore = create<EditorState>((set, get) => ({
  project: null,
  isLoading: true,
  error: null,
  selectedElementIds: [],
  mediaUrls: {},
  isPlaying: false,

  loadProject: async (id) => {
    set({ isLoading: true, error: null });
    try {
      const result = await storageService.loadProject({ id });
      if (!result) {
        set({ isLoading: false, error: `Project "${id}" not found` });
        return;
      }
      const urls: Record<string, string> = {};
      for (const el of result.project.scenes.tracks.elements) {
        if ('mediaId' in el && el.mediaId) {
          const asset = await storageService.loadMediaAsset({
            projectId: id,
            id: (el as { mediaId: string }).mediaId,
          });
          if (asset?.url) urls[el.id] = asset.url;
        }
      }
      set({ project: result.project, isLoading: false, mediaUrls: urls });
    } catch (error) {
      set({ isLoading: false, error: error instanceof Error ? error.message : String(error) });
    }
  },

  updateScene: (patch) => {
    const { project } = get();
    if (!project) return;
    const updated: TProject = {
      ...project,
      scenes: { ...project.scenes, ...patch, updatedAt: new Date() },
    };
    set({ project: updated });
    storageService.saveProject({ project: updated });
  },
}));

import { useSyncExternalStore } from 'react'
import { useEditorStore } from './editor-store'
import type { EditorState } from './editor-store'

const subscribeNone = () => () => {}

export function useEditor(): EditorState
export function useEditor<T>(selector: (state: EditorState) => T): T
export function useEditor<T>(
  selector?: (state: EditorState) => T,
): EditorState | T {
  const subscribe = (onChange: () => void) =>
    useEditorStore.subscribe(onChange)

  const getSnapshot = (): EditorState | T => {
    const state = useEditorStore.getState()
    return selector ? selector(state) : state
  }

  return useSyncExternalStore(
    selector ? subscribe : subscribeNone,
    getSnapshot,
    getSnapshot,
  ) as EditorState | T
}

export const setData = (storageKey: string, value: any) => {
  try {
    const jsonValue = JSON.stringify(value);
    const encrypted = CryptoJS.AES.encrypt(jsonValue, SECRET_KEY).toString();
    localStorage.setItem(storageKey, encrypted);
    window.dispatchEvent(new Event("storage"));
  } catch (e) {
    console.error("Gagal menyimpan di localStorage", e);
    return null;
  }
};

export const getData = (storageKey: string) => {
  try {
    const encrypted = localStorage.getItem(storageKey);
    if (!encrypted) return null;
    const bytes = CryptoJS.AES.decrypt(encrypted, SECRET_KEY);
    const decrypted = bytes.toString(CryptoJS.enc.Utf8);
    if (!decrypted) {
      localStorage.removeItem(storageKey);
      return null;
    }
    return JSON.parse(decrypted);
  } catch (e) {
    localStorage.removeItem(storageKey);
    return null;
  }
};

