import type { TProject } from "@/types/project";
import { IndexedDBAdapter, deleteDatabase } from "./indexeddb-adapter";
import type { MediaAsset, MediaAssetData, SerializedProject, StorageConfig } from "./types";
import { OPFSAdapter } from "./opfs-adapter";
import { isStorageQuotaExceededError, StorageQuotaExceededError } from "./quota";

class StorageService {
  private projectsAdapter: IndexedDBAdapter<SerializedProject>;
  private config: StorageConfig;

  constructor() {
    this.config = {
      projectsDb: "video-generator-projects",
      mediaDb: "video-generator-media",
    };

    this.projectsAdapter = new IndexedDBAdapter<SerializedProject>({
      dbName: this.config.projectsDb,
      storeName: "projects",
      version: 1,
    });
  }

  // Factory providing project-partitioned storage adapters
  private getProjectMediaAdapters({ projectId }: { projectId: string }) {
    const mediaMetadataAdapter = new IndexedDBAdapter<MediaAssetData>({
      dbName: `${this.config.mediaDb}-${projectId}`,
      storeName: "media-metadata",
    });

    const mediaAssetsAdapter = new OPFSAdapter(`media-files-${projectId}`);

    return { mediaMetadataAdapter, mediaAssetsAdapter };
  }

  isQuotaExceededError({ error }: { error: unknown }): boolean {
    return isStorageQuotaExceededError({ error });
  }

  async saveMediaAsset({
    projectId,
    mediaAsset,
  }: {
    projectId: string;
    mediaAsset: MediaAsset;
  }): Promise<void> {
    const { mediaMetadataAdapter, mediaAssetsAdapter } =
      this.getProjectMediaAdapters({ projectId });

    const metadata: MediaAssetData = {
      id: mediaAsset.id,
      name: mediaAsset.name,
      type: mediaAsset.type,
      size: mediaAsset.file.size,
      width: mediaAsset.width,
      height: mediaAsset.height,
      thumbnailUrl: mediaAsset.thumbnailUrl,
    };

    try {
      // Step 1: Write raw blob to Origin Private File System
      await mediaAssetsAdapter.set({
        key: mediaAsset.id,
        value: mediaAsset.file,
      });

      // Step 2: Write structured metadata to project-scoped IndexedDB
      await mediaMetadataAdapter.set({
        key: mediaAsset.id,
        value: metadata,
      });
    } catch (error) {
      // Rollback: delete orphaned binary file on failure
      try {
        await mediaAssetsAdapter.remove(mediaAsset.id);
      } catch {
        // Ignore cleanup failures to preserve original error
      }

      if (this.isQuotaExceededError({ error })) {
        throw new StorageQuotaExceededError({
          requiredBytes: mediaAsset.file.size,
        });
      }

      throw error;
    }
  }

  async deleteProject({ id }: { id: string }): Promise<void> {
    await this.projectsAdapter.remove(id);
    await deleteDatabase({ dbName: `${this.config.mediaDb}-${id}` });
  }
}

export const storageService = new StorageService();

export class StorageQuotaExceededError extends Error {
  readonly requiredBytes?: number;

  constructor({ requiredBytes }: { requiredBytes?: number } = {}) {
    super("Storage quota exceeded. Please free up space.");
    this.name = "StorageQuotaExceededError";
    this.requiredBytes = requiredBytes;
  }
}

export const isStorageQuotaExceededError = ({ error }: { error: unknown }): boolean => {
  if (error instanceof StorageQuotaExceededError) return true;
  if (error instanceof DOMException && (error.name === "QuotaExceededError" || error.code === 22)) {
    return true;
  }
  return false;
};

export class OPFSAdapter implements StorageAdapter<File> {
  private directoryName: string;

  constructor(directoryName = "media") {
    this.directoryName = directoryName;
  }

  private async getDirectory(): Promise<FileSystemDirectoryHandle> {
    const opfsRoot = await navigator.storage.getDirectory();
    return await opfsRoot.getDirectoryHandle(this.directoryName, {
      create: true,
    });
  }

  async get(key: string): Promise<File | null> {
    try {
      const directory = await this.getDirectory();
      const fileHandle = await directory.getFileHandle(key);
      return await fileHandle.getFile();
    } catch (error) {
      if ((error as Error).name === "NotFoundError") {
        return null;
      }
      throw error;
    }
  }

  async set({ key, value: file }: { key: string; value: File }): Promise<void> {
    const directory = await this.getDirectory();
    const fileHandle = await directory.getFileHandle(key, { create: true });
    const writable = await fileHandle.createWritable();

    await writable.write(file);
    await writable.close();
  }

  async remove(key: string): Promise<void> {
    try {
      const directory = await this.getDirectory();
      await directory.removeEntry(key);
    } catch (error) {
      if ((error as Error).name !== "NotFoundError") {
        throw error;
      }
    }
  }

  static isSupported(): boolean {
    return "storage" in navigator && "getDirectory" in navigator.storage;
  }
}

let ctx: AudioContext | null = null;

function getContext(): AudioContext {
  if (!ctx) {
    ctx = new AudioContext();
  }
  if (ctx.state === "suspended") {
    ctx.resume();
  }
  return ctx;
}

const decodedBuffers = new Map<string, AudioBuffer>();
const activeSources = new Map<string, { source: AudioBufferSourceNode; gain: GainNode }>();

export async function decodeAudio(mediaId: string, file: File): Promise<void> {
  const c = getContext();
  const arrayBuffer = await file.arrayBuffer();
  const buffer = await c.decodeAudioData(arrayBuffer);
  decodedBuffers.set(mediaId, buffer);
}

export function playAudio({
  mediaId,
  offsetSec,
  muted,
  trimStartSec = 0,
}: {
  mediaId: string;
  offsetSec: number;
  muted: boolean;
  trimStartSec?: number;
}): void {
  const existing = activeSources.get(mediaId);
  if (existing) {
    existing.source.onended = null;
    try { existing.source.stop(); } catch { /* no-op */ }
  }

  const buffer = decodedBuffers.get(mediaId);
  if (!buffer) return;

  const c = getContext();
  const source = c.createBufferSource();
  source.buffer = buffer;

  const gain = c.createGain();
  gain.gain.value = muted ? 0 : 1;

  source.connect(gain);
  gain.connect(c.destination);

  const effectiveOffset = Math.max(0, offsetSec + trimStartSec);
  const clampedOffset = Math.max(0, Math.min(effectiveOffset, buffer.duration - 0.01));
  source.start(0, clampedOffset);

  source.onended = () => {
    activeSources.delete(mediaId);
  };
  activeSources.set(mediaId, { source, gain });
}

export function scrubAudio({ mediaId, offsetSec, muted, trimStartSec = 0 }: any): void {
  const buffer = decodedBuffers.get(mediaId);
  if (!buffer) return;

  const c = getContext();
  const source = c.createBufferSource();
  source.buffer = buffer;
  const gain = c.createGain();
  gain.gain.value = muted ? 0 : 1;

  source.connect(gain);
  gain.connect(c.destination);

  const effectiveOffset = Math.max(0, offsetSec + trimStartSec);
  const clampedOffset = Math.max(0, Math.min(effectiveOffset, buffer.duration - 0.01));
  source.start(0, clampedOffset);
  source.stop(c.currentTime + 0.3);

  source.onended = () => { scrubNode = null; };
  scrubNode = { source, gain };
}

useEffect(() => {
  if (!isPlaying) return;

  resumeAudioContext();
  const wallStartRef = { current: performance.now() };
  const playheadStartRef = { current: playheadTimeRef.current };
  let rafId: number;

  const tick = () => {
    if (!isPlayingRef.current) return;

    const elapsedMs = performance.now() - wallStartRef.current;
    const elapsed = mediaTimeFromSeconds({ seconds: elapsedMs / 1000 });
    const nextTime = addMediaTime({ a: playheadStartRef.current, b: elapsed });

    if (nextTime >= effectiveDuration) {
      seekRef.current(effectiveDuration);
      pauseRef.current();
      return;
    }

    const tracksEl = tracksScrollRef.current;
    const scrollLeft = tracksEl?.scrollLeft ?? 0;
    const centerPixel = timelineTimeToPixels({
      time: nextTime,
      zoomLevel: zoomLevelRef.current,
    });
    const playheadLeft = getCenteredLineLeft({ centerPixel }) - scrollLeft;

    if (playheadRef.current) {
      playheadRef.current.style.left = `${playheadLeft}px`;
    }

    const playheadSec = mediaTimeToSeconds({ time: nextTime });
    const nowPlaying = new Set<string>();

    for (const ael of audioElementsRef.current) {
      const startSec = mediaTimeToSeconds({ time: ael.startTime });
      const endSec = startSec + mediaTimeToSeconds({ time: ael.duration });
      if (playheadSec >= startSec && playheadSec < endSec) {
        nowPlaying.add(ael.mediaId);
        if (!playingMediaIds.current.has(ael.mediaId)) {
          playAudio({
            mediaId: ael.mediaId,
            offsetSec: playheadSec - startSec,
            muted: isAudioMutedRef.current,
            trimStartSec: mediaTimeToSeconds({ time: ael.trimStart }),
          });
        }
      }
    }

    for (const id of playingMediaIds.current) {
      if (!nowPlaying.has(id)) stopAudio(id);
    }
    playingMediaIds.current = nowPlaying;

    rafId = requestAnimationFrame(tick);
  };

  rafId = requestAnimationFrame(tick);
  return () => {
    cancelAnimationFrame(rafId);
    seekRef.current(currentTimeRef.current);
    stopAllAudio();
  };
}, [isPlaying, effectiveDuration]);

